// A19 会话详情 · 真人接管 —— 意向确认后 AI 代理退场，招聘顾问真人上场谈落地细节。
//
// 结构：返回栏（居中标题 + ⋯）→ 顶部操作排（看职位 / 电话 / 微信）→
// 已确认意向的职位摘要卡 → 消息流（含代理提醒灰条与日期分隔）→
// 真输入条（深绿边 + ◈ 代理符）。
//
// 气泡、系统条与自动滚到底都复用 直聊会话.tsx 导出的共用件，
// 样式同样引 直聊会话.module.css —— 两屏的消息流必须像素一致，所以不另写一份。
//
// 双盲：这一屏在意向确认之后，双盲已解除，对方真名与联系方式本来就互相可见，
// 所以顶部操作排是「看」不是「换」，没有申请-同意这一步（见 真人会话操作栏.tsx）。

import { useState } from 'react';
import 样式 from './真人会话.module.css';
import 共用样式 from './直聊会话.module.css';
import 谈详情样式 from './在谈详情.module.css';
import 详析样式 from './职位详情.module.css';
import { 消息条, use自动滚到底 } from './直聊会话';
import { 硬性行们 } from './职位详情';
import 真人会话操作栏 from './真人会话操作栏';
import { 次级页外壳, 公司字标, 返回栏, 滚动区, 真输入条 } from '../组件/通用';
import 适配环 from '../组件/适配环';
import { 公文包图标 } from '../组件/图标';
import 举报层 from '../组件/举报层';
import { use导航 } from '../路由/导航钩子';
import { 路径 } from '../路由/路径表';
import { use应用状态 } from '../状态/应用状态';
import { 公司路由键 } from '../数据/公司档案';
import {
  取在谈岗位详情,
  在谈列表 as 在谈种子列表,
  市场列表,
  真人会话 as 真人会话数据,
} from '../数据/模拟数据';
import type { 在谈单, 会话条 } from '../数据/类型';

/** 这一屏写死服务 J-01 这一单（顶部职位卡、看职位层、「查看 ›」都指同一个岗）。
 *  编号只在这里出现一次，避免三个入口哪天被改歪、指向不同的岗。 */
const 本单编号 = 'J-01';

export default function 真人会话() {
  const { 返回, 跳转 } = use导航();
  const { 状态 } = use应用状态();
  const [消息, 设消息] = useState<会话条[]>(真人会话数据.消息);
  const [草稿, 设草稿] = useState('');
  // 标注 2026-08-20 09:36 / 2026-08-21 10:14：意向确认即自动互换，只显示对方的。
  // 2026-08-22：原先那两张联系卡钉在消息流顶部，现在整块挪进顶部操作排的展开区 ——
  // 卡片组件与复制逻辑没换，只换了位置。留在流里会和顶部那排讲同一件事两遍，
  // 而它本来就钉在流顶（在日期分隔条之前），已经不在时间轴上、不带任何时间信息；
  // 「联系方式是这一刻互换的」这句话由职位卡的归档行（15:22 意向确认）继续承担。
  // 右上「⋯」拉起的举报层：这一屏对面是真人顾问，屏蔽指向他所属的机构
  const [举报层开, 设举报层开] = useState(false);
  const 底部锚 = use自动滚到底(消息);

  // 「看职位」层要渲染的那一单。优先取全局在谈列表（用户可能在在谈详情里改过它），
  // 取不到再退回种子数据 —— 退出谈判会把这一单从全局列表里移除，但这一屏是
  // 意向确认之后的场景，职位本身还得看得见，不能因为归档就点开一片空白。
  const 本单 =
    状态.在谈列表.find((条) => 条.编号 === 本单编号) ??
    在谈种子列表.find((条) => 条.编号 === 本单编号) ??
    null;

  // 发送：草稿去空后追加到本地消息流（真人页的消息不带时间戳，与源一致）
  const 发送 = () => {
    const 内容 = 草稿.trim();
    if (!内容) return;
    const 新条: 会话条 = { 编号: Date.now(), 角色: '我', 内容 };
    设消息((旧) => [...旧, 新条]);
    设草稿('');
  };

  return (
    <次级页外壳 对话底>
      <返回栏
        返回={返回}
        标题="林筱"
        副标题="铨衡人才 · 招聘顾问"
        居中标题
        右侧={
          <button
            className={`${共用样式.更多} 可点`}
            onClick={() => 设举报层开(true)}
            aria-label="举报"
          >
            ⋯
          </button>
        }
      />

      {/* 顶部操作排：主项「看职位」2026-08-22 由跳转改成盖一层全屏详情（产品负责人反馈：
          「点开后是一个和主页一样的页面，但是不要跳转」）。层里铺的就是在谈详情
          「职位详情」Tab 看到的那份内容，路由不动、返回栈不加深，
          「继续沟通」关掉层就回到聊天，滚动位置与草稿都还在。 */}
      <真人会话操作栏
        主项名="看职位"
        主项图标={<公文包图标 尺寸={18} 色="#3f7a1f" />}
        主项内容={本单 ? <职位内容 单={本单} /> : null}
        联系方式={真人会话数据.联系方式}
      />

      <滚动区>
        <div className={`${共用样式.消息流} ${共用样式.消息流上留白}`}>
          <职位卡 查看={() => 跳转(路径.在谈详情(本单编号))} />

          {消息.map((条) => (
            <消息条 key={条.编号} 条={条} 对方首字="林" />
          ))}
          <div ref={底部锚} />
        </div>
      </滚动区>

      <真输入条
        占位="输入消息…"
        值={草稿}
        改变={设草稿}
        发送={发送}
        右侧图标={<span className={样式.代理符}>◈</span>}
      />

      {举报层开 ? (
        <举报层
          对象名="林筱 · 铨衡人才"
          屏蔽名称="铨衡人才"
          关闭={() => 设举报层开(false)}
        />
      ) : null}
    </次级页外壳>
  );
}

// ── 「看职位」全屏层的正文：匹配度分析 → JD / 职位要求 → 对接人 → 公司 ──
// 与 在谈详情.tsx 的「职位详情」Tab 是同一份内容、同一份取数（取在谈岗位详情）、
// 同一批样式类，所以两处看到的职位必然一样。
// 这里之所以重写了一遍 JSX 而不是复用：那个 Tab 是 在谈详情.tsx 内部的私有组件，
// 本轮的改动范围不含那个文件（并行改动，不越界动别人的文件）。后续应把它提成
// 共享组件，两边一起引 —— 在那之前，改 JD 版式时这两处必须一起改。
function 职位内容({ 单 }: { 单: 在谈单 }) {
  const { 跳转 } = use导航();
  const { 状态: 全局 } = use应用状态();
  const 详 = 取在谈岗位详情(单);
  // 适配分的依据：委托进来的 M- 单直接借市场岗位上的证据，剧本 J- 单用自己的同名字段
  const 证据源 = 市场列表.find((岗) => 岗.编号 === 单.编号) ?? 单;
  const 硬性 = 硬性行们(证据源, 全局.简历技能);

  return (
    <div className={谈详情样式.详情列}>
      {/* 匹配度分析：与看市场职位详情同一张卡（样式直接复用那边的 module）*/}
      <div className={详析样式.卡}>
        <div className={详析样式.适配头}>
          <span className={详析样式.卡标题}>匹配度分析</span>
          <适配环 分={单.适配分} 标={null} 尺寸={44} />
        </div>
        {硬性.length ? (
          <>
            <div className={详析样式.证据组标}>硬性要求</div>
            {硬性.map((行) => (
              <div key={行.文} className={详析样式.证据行}>
                <span className={行.过 ? 详析样式.适配过 : 详析样式.适配差}>
                  {行.过 ? '✓' : '✗'}
                </span>
                <span className={详析样式.证据文}>{行.文}</span>
              </div>
            ))}
          </>
        ) : null}
        {证据源.技能要求?.length ? (
          <>
            <div className={详析样式.证据组标}>技能</div>
            <div className={详析样式.技能行}>
              {证据源.技能要求.map((技) => {
                const 命中 = 全局.简历技能.some((有) => 有.includes(技) || 技.includes(有));
                return (
                  <span key={技} className={命中 ? 详析样式.技能中 : 详析样式.技能缺}>
                    {命中 ? `✓ ${技}` : 技}
                  </span>
                );
              })}
            </div>
          </>
        ) : null}
      </div>

      <div className={谈详情样式.详情卡}>
        <div className={谈详情样式.详情标题}>职位详情</div>
        {详.职位详情.map((行) => (
          <div key={行} className={谈详情样式.详情正文}>
            {行}
          </div>
        ))}
        <div className={谈详情样式.详情小标题}>职位要求</div>
        {详.职位要求.map((行) => (
          <div key={行} className={谈详情样式.详情正文}>
            {行}
          </div>
        ))}
      </div>

      {/* 对接人卡：取不到这一单的对接人时整张卡不渲染 —— 宁可少一张卡，也不编一个假人出来 */}
      {详.对接人 ? (
        <div className={`${谈详情样式.详情卡} ${谈详情样式.对接人卡}`}>
          <span className={谈详情样式.对接人头像}>
            <span className={谈详情样式.对接人首字}>{详.对接人.首字}</span>
          </span>
          <div className={谈详情样式.对接人文本}>
            <div className={谈详情样式.对接人名}>
              {详.对接人.姓名} · {单.公司}{' '}
              <span className={谈详情样式.对接人职务}>{详.对接人.职务}</span>
            </div>
            <div className={谈详情样式.对接人备注}>{详.对接人.备注}</div>
          </div>
        </div>
      ) : null}

      <div className={谈详情样式.详情卡}>
        {/* 整行可点，进公司主页。这一跳是用户主动要看另一个对象（公司），
            与「看职位不该跳走」不冲突：跳走的是公司页，回来按返回键即可。 */}
        <button
          className={`${谈详情样式.公司头行} 可点`}
          onClick={() => 跳转(路径.企业详情(公司路由键(单.公司)))}
        >
          <公司字标
            首字={单.公司首字}
            尺寸={44}
            圆角={14}
            底色="var(--墨)"
            字色="var(--荧光绿)"
            描边={false}
            字号={19}
          />
          <span className={谈详情样式.公司文本}>
            <span className={`${谈详情样式.公司名} 单行`}>{单.公司}</span>
            <span className={`${谈详情样式.公司简介} 单行`}>{单.公司简介}</span>
          </span>
          <span className={谈详情样式.尖括号}>›</span>
        </button>
        {详.公司.正文 ? <div className={谈详情样式.公司正文}>{详.公司.正文}</div> : null}
        {详.公司.标签.length ? (
          <div className={谈详情样式.公司标签行}>
            {详.公司.标签.map((标签) => (
              <span key={标签} className={谈详情样式.公司标签}>
                {标签}
              </span>
            ))}
          </div>
        ) : null}
      </div>
    </div>
  );
}

// ── 顶部职位摘要卡：意向已确认，谈判档案归档，「查看 ›」回到该单的在谈详情 ──
function 职位卡({ 查看 }: { 查看: () => void }) {
  const 卡 = 真人会话数据.职位卡;
  return (
    <div className={样式.职位卡}>
      <div className={样式.职位卡头行}>
        <div className={`${样式.职位卡标题} 单行`}>{卡.职位}</div>
        <span className={`${样式.职位卡薪资} 等宽数字`}>{卡.薪资}</span>
      </div>
      <div className={样式.职位卡条件}>{卡.条件行}</div>
      <div className={样式.职位卡底}>
        <div className={`${样式.职位卡归档} 单行`}>{卡.归档行}</div>
        <button className={`${样式.职位卡链接} 可点`} onClick={查看}>
          查看 ›
        </button>
      </div>
    </div>
  );
}
